INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (7978,3,1,'နှစ်ဆယ့်တစ်လုံးမြောက်မွန်ဗျည်း။',NULL)
,(7979,3,4,'ပြုလုပ်သည်။','ပအ္စာ = ဆရာလုပ်သည်။ || “မူပဒၟံၚ်ရော” = “ဘာလုပ်နေသလဲ။” || ပအရဴဂဴ = အလေးအမြတ်ပြုသည်။')
,(7979,3,9,'တားမြစ်ခြင်းကိုပြသောစကားလုံး။ (‘လ္ပ’ ၏အတိုကောက်) || “ပွသာ်ဏအ် လက်ကြဴပပညိ။” = “ဤအပြုအမူမျိုး နောက်ခါမပြုလုပ်ပါနှင့်။”')
,(7980,3,10,'(န) ပင်ကိုသဘော။ ပင်ကိုစရိုက်။ အလေ့သဘော။ ပကတိ။','“ယွံတၠညး၊ ချေံၜါဂှ် ပက္ကတိဍေံမခိုဟ်သၟဟ်ဂှ် ဟွံဒှ်ရ၊ မၞုံပက္ကတိမကြံကြသၟဟ်ဂှ်ဒှ်ရ။” (ဇ—၁၅၈။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ဤမြင်းနှစ်စီးတို့သည် ကောင်းသောပင်ကိုသဘော ရှိကုန်သည်မဟုတ်။ တူညီသောကြမ်းသော ပင်ကိုသဘောရှိကုန်၏။” || “ယွံကောန်၊ မပတၠဂၟံၚ်ရောၚ်သွံ။ မၞးမၞုံပက္ကတိမဂ္ၚေၚ်ဋ္ဌာန်စၞေဟ်ရောၚ်သွံ။၊ ပ္ဍဲဋ္ဌာန်စၞေဟ် မဂွံဒုၚ်ဒယှ်တှ်ဒေါဝ်ပေဲါရောၚ်” အ္စာစိၚ်ဂးကဵုစိၚ်မ္ၚဵုဂှ်ရ။ (ဇ—၁၈၂။ အစွောံ။) = “ချစ်သား၊ သင်သည် ရဲရင့်၏။ စစ်မြေပြင်­ ကျက်စားသောအလေ့ရှိ၏။ စစ်မြေပြင်­ ပွဲလယ်­ အကျော်အစောခံသောဆင်တော်တည်း။” || “(သရဂှ်စိန်အာ) ပၞေတ်သရဟွံမွဲရ။ ဒှ်ညံၚ်ပက္ကတိဇိုၚ်တရေံဂှ်ရ။” (ဇ—၅၃၃။ အစွောံ။) = “အနာဒဏ်ရာကျက်၍ အနာရွတ်မထင်။ မူလပကတိခြေထောက်ကဲ့သို့ဖြစ်၏။”')
,(7981,3,10,'(နဝိ) သာမန်။ သာမည။ အထူးမဟုတ်သော။ မထင်ရှားသော။','မၞိဟ်ပက္ကတိ = သာမန်လူ။ မထင်ရှားသောလူ။ || ပုၚ်ပက္ကတိ = သာမန်ထမင်း။ (အုန်းထမင်း၊ ထောပတ်ထမင်းစသည်မဟုတ်သော။) || “သၟတ်ဗြဴဂှ် မပတၠစရာဲရုပ်ဂေါဝ်လောန် ကလိကၠေံရုပ်မၞိဟ်ပက္ကတိ ညံၚ်ရုပ်ကောန်ဒေဝတဴဗြဴအဆေဝ်သွဝ်ကီုရ။” (ဇ—၃၈ဝ။ အစွောံ။) = “ထိုမိန်းမပျိုသည်ရုပ်အဆင်းအလွန်တင့်တယ်၏။ လူသာမန်တို့၏ရုပ်အဆင်းကိုလွန်၍ နတ်သမီးရုပ်အဆင်းကဲ့သို့ ဖြစ်၏။” || “ကြုက်အဘန်တဵုဂှ် တဴပ္ဍဲဂြိုပ်ဟေမဝန် ပ္ဍဲဂေါဟ်တၟံထဝ် ဒေဝတဴတံမမၚ်လဝ် ဒှ်ပြဘိုက်ဒေဝတဴရောၚ်။ မၞိဟ်ပက္ကတိဂှ် အာဟွံစိုပ်ရ။” (ဇ—၂၈၁။ အစွောံ။) = “အဗ္ဘန္တရသရက်သီးသည်ကား ဟိမဝန္တာတော ရွှေတောင်လိုဏ်­ တည်ရှိ၏။ နတ်တို့စောင့်ရှောက်ထားသော နတ်တို့၏အသုံးအဆောင်ဖြစ်၏။ လူသာမန်တို့ မသွားရောက်နိုင်။” || “(ကောန်ဗြဴသေဋ္ဌဳဂှ်) ပလွေဟ်ညးပက္ကတိတုဲ စှ်ေအာနူပြာသာဒ်ဇကုတုဲ—။” (ဇ—၂၃၂။ အစွောံ။) = “(ထိုသူဋ္ဌေးသမီးသည်) မထင်ရှားသောအသွင်ဖြင့် ပြာသာဒ်မှဆင်းသက်၍—။” (ညောင်ကန်) || “ကောန်ၚာ်ဂှ် ပက္ကတိမၞိဟ်ဟွံသေၚ်၊ ဗောဓိသတ်ရောၚ်။” (ဇ—၄၄၅။ အစွောံ။) = “ထိုသူငယ်သည် ဟုတ်ဟုတ်ငြားငြားသောသူငယ်မဟုတ်၊ ဘုရားလောင်းလျှင်တည်း။” (ညောင်ကန်)')
,(7982,3,4,'ကတိကဝတ်ပြုသည်။',NULL)
,(7983,3,4,'ဆင်းရဲပူပန်အောင်လုပ်သည်။','“ဒပိုန်ဒေဝဒတ်ဝွံ သ္ပကတဴကဵုတဳလမၞုံပိုန်ကျာ်တြဲ—။” (ဇ—၁၂၂။ အစွောံ။) = “အရှင်ဒေဝဒတ်သည် မြတ်စွာဘုရားအား ပူပန်ဆင်းရဲရအောင်လုပ်၏။” || “ကောန်ဗြဴအဲဝွံလေဝ် — ဍေံကၠုၚ်ပကတဴစိုတ်ပိုဲ—။” (ဇ—၅၃၁။ အစွောံ။) = “ငါ့သမီးသည်လည်း ငါတို့စိတ်ပူပန်ဆင်းရဲအောင်ပြု၏။”')
,(7984,3,4,'ဟန်ဆောင်သည်။ အယောင်ဆောင်သည်။','“ဍေံပကလော်ယဲတုဲ ပလဳဘာရ။”= “သူဖျားချင်ဟန်ဆောင်ပြီး ကျောင်းပြေးသည်။” || “(ဗောဓိသတ်သီုကွဳမသုန်ကၠံ) ကာလမအာစိုပ်ကန္တာကလော်ဂှ် (ကလော်တံဂှ်) ဍေံပကလော်မဒစးကၠုၚ် ထ္ၜးဇကုကဵုဗောဓိသတ်ရ။” (ဇ—၁။အစွောံ။) = “ဘုရားလောင်းသည် လှည်းငါးရာတို့ဖြင့် ကန္တာရသို့ရောက်သော် ဘီလူးတို့သည်ဘုရားလောင်းအား ခရီးရင်ဆိုင်မှလာဟန်ပြု၍ ကိုယ်ထင်ပြ၏။” || ‘ကလံက်ပ’ (ကြိ) လည်းရှု။')
,(7985,3,4,'လှောင်ပြောင်သည်။ ပြက်ရယ်ပြုသည်။','“သၟိၚ်ဝွံ — ကောန်ဗြဴဇကုမွဲကီုသီုညးထပှ်က္ဍိုၚ်ဗ္တာၚ် ဂွံကဵုဏာလိက်ဂှ် ပမွဲသွတ်သွာ ပကသံက်ကသာကဵုပိုဲရောၚ်သွံ” သၟိၚ်ထပှ်က္ဍိုၚ်ဗ္တာၚ်ဂး။ (ဇ—၅၃၁။ အစွောံ။) = “ဤမင်းကား မိမိ၏သမီးတော်တစ်ယောက်တည်းကို ငါတို့ခုနစ်ပြည်ထောင်မင်းတို့အား စာဆက်ခြင်းသည်ကား ငါတို့ကို မထီမဲ့မြင်ပြုခြင်း ပြက်ရယ်ပြုခြင်းပင်တည်း” ဟုခုနစ်ပြည်ထောင်မင်းတို့ဆိုကုန်၏။')
,(7986,3,4,'တိုင်ပင်သည်။','“ဗညာနဲပကသပ်ဂၞန်ကဵုအ္စာမပေၚ်။” (အကြီုရာဇာဓိရာဇ်) = “ဗညားနွဲ့သည် ဆရာမပိုင်နှင့်တိုင်ပင်၏။”')
,(7987,3,4,'ဂရုစိုက်သည်၊ အလေးထားသည်။','“ဗှ်ေဟွံဆာန်အဲဂှ်လေဝ် အဲဟွံဆာန်ဗှ်ေကီုရ။ ဗှ်ေဟွံပကာလေဝ် အဲဟွံပကာကီုရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “နင်ငါ့ကိုမချစ်လျှင် ငါလည်းနင့်ကိုမချစ်ပါ။ နင်ဂရုမစိုက်လျှင် ငါလည်းဂရုမစိုက်ပါ။” || “လၟုဟ်တုန်ရ၊ ညိဟွံပကာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ယခုအခါ စိုးစဉ်းမျှဂရုမစိုက်။”')
,(7988,3,4,'သေဆုံးသည်။','“သမ္ဘာသေဋ္ဌဳ ပကာဂစိုတ်—။” (ဇ—၁၃၇။ အစွောံ။) = “သူဋ္ဌေး၏မယားသည် သေ၏။” || “ဒကာဗြဴဂှ် ယဲက္တဵုဒှ်တုဲ ပကၠေံကာဂစိုတ်ရ။” (ဇ—၁၄၆။ အစွောံ။) = “ထိုဒကာမသည်လည်း ရောဂါဖြစ်၍ သေ၏။”')
,(7989,3,4,'(ဘုရား၊ ဘုရင်စသည့်မြင့်မြတ်သူ) ပြုံးတော်မူသည်။','“ကျာ်တြဲမၠာ်မွဲသၟတ်ဗြဴဂှ်တုဲ ပကာဂအီရ။” (ဇ—၄၁၅။ အစွောံ။) = “မြတ်စွာဘုရားရှင်သည် ထိုသတို့သမီးငယ်ကို ကြည့်တော်မူ၍ ပြုံးတော်မူ၏။” || “ဗညာနဲဂွံမိၚ် သၟိၚ်တိဿကုမ္မာလ္ၚောဝ်ပ္တီတုဲ ပကာဂအီ။” (အကြီုရာဇာဓိရာဇ်) = “ဗညားနွဲ့သည် သမိန်တိဿကုမ္မာ ရှိခိုးလျှောက်တင်သည်ကိုကြား၍ ပြုံးတော်မူ၏။” || “တၠညးပကာဂမ္အီ။” (အကြီုရာဇာဓိရာဇ်) = “ရှင်ဘုရင်ပြုံးတော်မူသည်။”')
,(7990,3,16,'(န) အပြား။ အထူးအပြား။ အခြင်းအရာ။','“ယွံဗမၞးသၚ်္ခ၊ ပ္ဍဲဋ္ဌာန်ဝွံပုၚ်ဍာ်ကီု သၞာသ္တိက်ကီု သၞာဂ္ဇံကီု မၞုံပက္ကရတၞဟ်ဟ်သာ် မပ္တံယာန်စိၚ်ချေံကီု နွံတဴရ။” (ဇ—၄၄၂။အစွောံ။) = “သင်္ခပုဏ္ဏား၊ ထမင်းအဖျော်သည်လည်းကောင်း အိပ်ရာနေရာသည်လည်းကောင်းအထူးထူးအပြားပြားများကုန်သော ဆင်ယာဉ်မြင်းယာဉ် အစရှိသည်တို့သည်လည်းကောင်း ငါ့အားရှိကုန်၏။” (ညောင်ကန်) || “ညးဗၞိက်တံဂှ် ဍေံရပ်ဂွံမြာ်ကၟက်မွဲတုဲ ဍေံဂဍတ်တဲတုဲ ကဵုဍေံဂြဴ၊ဍေံတက်တဲတုဲ ဍေံကဵုလှ်ေရ။ ဗွဲပကာရသာ်ဂှ် ဍေံပကတ်ပကေၚ်တုဲ—။” (ဇ—၃၃၉။ အစွောံ။) =“ကုန်သည်တို့သည် တစ်ခုသောဥဒေါင်းဖိုကို ဖမ်းရသည်ရှိသော် လက်ဖျစ်တီး၍ တွန်စေ၏။လက်ခုပ်တီး၍ ကစေ၏။ ထိုသို့သောအခြင်းအရာဖြင့် လေ့ကျင့်သင်ပေး၏။” || နာနာပက္ကရ =အမျိုးမျိုးအပြားပြား။ အမျိုးမျိုးအထွေထွေ။')
,(7991,3,4,'‘ပဝဵုမ္ၚဵု’ ရှု။',NULL)
,(7992,3,10,'(န) ပေါ်လွင်ထင်ရှားအောင် ဂုဏ်ဖော်ပြသမှု။ ပကာသန။',NULL)
,(7993,3,1,'ထောင်ချောက်။ ယန္တရား။ စက်။ (ပါဠိ—ယန္တ)','“ပ္ကီုလဝ်ပကဲတုဲ မဇကုဂှ် ပ္ဍဲဂၠံကဵုလောပ်ဒၟံၚ်ရ။” (သၠပတ်ဗုဒ္ဓဃောသာ) = “ယန္တရားကို စီရင်ထားပြီးလျှင် မိမိဖခင်အား အခန်းထဲ­ ဝင်နေစေ၏။” || “(မဟောသဓ) လိုန်ပကဲတရၚ်ဥမင်မွဲတုဲ တရၚ်ဂမၠိုၚ်ဒဝ်အာအိုတ်ရ။” (ပြကိုဟ်နဝဗျတ္တိ) = “မဟော်သဓာသည် ဥမင်တံခါးယန္တရားခလုတ်တစ်ခုကို နင်းလိုက်သောအခါတံခါးများအားလုံး ပိတ်သွား၏။”')
,(7993,3,4,'၁။ ထောင်ချောက်ဖြင့်ထောင်သည်။ (ယန္တရားဖြင့်) ဆင်သည်။','“အမရာခၞံကတိုၚ်သ္ၚိဍာ်တုဲ — ဂတဵုဇၞော်မွဲ ကၠောန်ပကဲလဝ် ပ္ဍဲပါၚ်ကတိုၚ်ဂှ်ရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “အမရာသည် အိမ်သာတွင်းကို စီရင်ပြီးလျှင် တွင်းဝ­ ယန္တရားထောင်ချောက်ဆင်ထား၏။” || “ပ္ကဲလဝ်စက်တြဴတန်ရ။” (သၠပတ်ဂမ္စာဲဓါတ်) = “စက်ယန္တရားခြောက်တန်ထောင်ထား၏။”')
,(7993,3,4,'၂။ တွဲလောင်းချသည်။','ပကဲဖျေံဇုက် = ကြိုးကိုတွဲလောင်းချသည်။ || “ကေတ်ဇုက် ပကဲဖျေံမ္ၚးကၟာၚ်ဍုၚ်တုဲ အ္စာမပေၚ်တိတ်အာ။” (အကြီုရာဇာဓိရာဇ်) =“ကြိုးကိုယူ၍ မြို့ရိုးအပြင်ဘက်သို့ တွဲလောင်းချပြီး ဆရာမပိုင်ထွက်သွား၏။” || ‘လကဲ’ ဟုလည်းရေးသည်။')
